func (da *ReconDestAgent) sqlDialectCountRows(ctx context.Context, tableName, pkColumn string) (int64, error) {
	if err := validateIdent(tableName); err != nil {
		return 0, err
	}
	qCtx, cancel := context.WithTimeout(ctx, da.cfg.QueryTimeout)
	defer cancel()

	var count int64
	sql := fmt.Sprintf("SELECT COUNT(*) FROM %s%s", quoteDialectRelation(tableName), da.finalModifier())
	if err := da.replica.WithContext(qCtx).Raw(sql).Scan(&count).Error; err != nil {
		return 0, err
	}
	return count, nil
}

